(5115668, 744757, 34938, '<td valign="top">Lovely...I like the use of the negative space in this, as well as your selected border...</td>', 'Lovely...I like the use of the negative space in this, as well as your selected border...', '2008-12-08 00:25:12.000000', NULL, 1),
