(5115677, 745230, 34938, '<td valign="top">GReat title and I would have to say a chance for a ribbon...10 from me, it''s faultless</td>', 'GReat title and I would have to say a chance for a ribbon...10 from me, it''s faultless', '2008-12-08 00:26:37.000000', NULL, 1),
(5115684, 745420, 96915, '<td valign="top">Cool, I had been hoping to enter a B/W sunset, but I didn''t quite have the right photo for a conversion.  Ballsy move, and I hope it does well.</td>', 'Cool, I had been hoping to enter a B/W sunset, but I didn''t quite have the right photo for a conversion.  Ballsy move, and I hope it does well.', '2008-12-08 00:27:36.000000', NULL, 1),
(5115697, 745038, 34938, '<td valign="top">great title and edit...well done 8</td>', 'great title and edit...well done 8', '2008-12-08 00:29:25.000000', NULL, 1),
(5115703, 745581, 34938, '<td valign="top">beautiful sky... conveys serenity</td>', 'beautiful sky... conveys serenity', '2008-12-08 00:30:14.000000', NULL, 1),
(5115708, 745178, 54645, '<td valign="top">I love the foreground and color, but the sun/sky have been over processed. Too much of an attempt to recover highlights. I think you could have cropped out the sun, and the image would have been something special.</td>', 'I love the foreground and color, but the sun/sky have been over processed. Too much of an attempt to recover highlights. I think you could have cropped out the sun, and the image would have been something special.', '2008-12-08 00:31:02.000000', NULL, 1),
(5115712, 745313, 54645, '<td valign="top">Love the foreground. Sky appears posterized. Composition is strong.</td>', 'Love the foreground. Sky appears posterized. Composition is strong.', '2008-12-08 00:32:17.000000', NULL, 1),
(5115715, 745573, 92643, '<td valign="top">i love the silhouettes, but i wish they stood out a little more....nice shot, though!</td>', 'i love the silhouettes, but i wish they stood out a little more....nice shot, though!', '2008-12-08 00:32:35.000000', NULL, 1),
(5115716, 745333, 34938, '<td valign="top">beautiful city silhouette...wonderful 8</td>', 'beautiful city silhouette...wonderful 8', '2008-12-08 00:32:59.000000', NULL, 1),
(5115774, 745552, 34938, '<td valign="top">great juxtaposition...well done...most won''t give you credit that is due so I will</td>', 'great juxtaposition...well done...most won''t give you credit that is due so I will', '2008-12-08 00:51:51.000000', NULL, 1),
(5115777, 745541, 34938, '<td valign="top">great light rays!</td>', 'great light rays!', '2008-12-08 00:52:11.000000', NULL, 1),
(5115785, 745461, 34938, '<td valign="top">a winner to me...the adding of the child is where it is different to all the other images...good luck and 9 from me</td>', 'a winner to me...the adding of the child is where it is different to all the other images...good luck and 9 from me', '2008-12-08 00:53:59.000000', NULL, 1),
(5115796, 744605, 34938, '<td valign="top">simplicity, bueaty, perfection....great image</td>', 'simplicity, bueaty, perfection....great image', '2008-12-08 00:58:00.000000', NULL, 1),
(5115806, 745502, 44579, '<td valign="top">The bright foreground keeps drawing my eyes away from the cityscape and mountains. Gotta love those prairie skys though. Great location to shoot from, I''ve been looking for a good one from the NE for a while now.</td>', 'The bright foreground keeps drawing my eyes away from the cityscape and mountains. Gotta love those prairie skys though. Great location to shoot from, I''ve been looking for a good one from the NE for a while now.', '2008-12-08 01:02:48.000000', NULL, 1),
(5115810, 745282, 44579, '<td valign="top">I wish I could vote on this photo. It would be a 10. Great job!</td>', 'I wish I could vote on this photo. It would be a 10. Great job!', '2008-12-08 01:04:33.000000', NULL, 1),
(5115835, 744169, 96915, '<td valign="top">Creative.  I was hoping that with all the fretting about not having access to a sunset or sunrise, that someone would invent one.  Good job.</td>', 'Creative.  I was hoping that with all the fretting about not having access to a sunset or sunrise, that someone would invent one.  Good job.', '2008-12-08 01:21:45.000000', NULL, 1),
(5115858, 745282, 47541, '<td valign="top">This is very funny!</td>', 'This is very funny!', '2008-12-08 01:35:06.000000', NULL, 1),
(5115859, 745065, 69668, '<td valign="top">We do have some amazing sunsets here in the PNW.  Nice image.</td>', 'We do have some amazing sunsets here in the PNW.  Nice image.', '2008-12-08 01:36:49.000000', NULL, 1),
(5115862, 745617, 43088, '<td valign="top">I like the light in the window. Too bad you did not have more color in the sky (you take what you are given) but the clouds are great.</td>', 'I like the light in the window. Too bad you did not have more color in the sky (you take what you are given) but the clouds are great.', '2008-12-08 01:37:38.000000', NULL, 1),
(5115864, 745393, 43088, '<td valign="top">Nice colors/ tones. Could use a little more sharpness.</td>', 'Nice colors/ tones. Could use a little more sharpness.', '2008-12-08 01:39:30.000000', NULL, 1),
(5115868, 745526, 43088, '<td valign="top">Beautiful colors. For a minor suggestion I might have tried a lower angle and a bit further back from the person to get more of them in the frame.</td>', 'Beautiful colors. For a minor suggestion I might have tried a lower angle and a bit further back from the person to get more of them in the frame.', '2008-12-08 01:40:52.000000', NULL, 1),
(5115871, 745349, 57260, '<td valign="top">Brilliant Capture! This is just so different from all the others. My choice for blue. Well done.</td>', 'Brilliant Capture! This is just so different from all the others. My choice for blue. Well done.', '2008-12-08 01:41:52.000000', NULL, 1),
(5115875, 745621, 43088, '<td valign="top">Difficult lighting situation to work with.  It seems a little dark to me but if you lighten it more you lose more of the sky/ sun.</td>', 'Difficult lighting situation to work with.  It seems a little dark to me but if you lighten it more you lose more of the sky/ sun.', '2008-12-08 01:42:40.000000', NULL, 1),
(5115877, 744791, 43088, '<td valign="top">Nice idea to include some subject in the foreground but I think the sign does not contribute to the picture. Maybe something else?</td>', 'Nice idea to include some subject in the foreground but I think the sign does not contribute to the picture. Maybe something else?', '2008-12-08 01:43:53.000000', NULL, 1),
(5115881, 745057, 43088, '<td valign="top">It looks like there is a film or something over the picture. You have no real black- I can understand that you may have been trying to perhaps get some more detail from the shadows but it makes the overall picture look washed out.  A bit of contrast is generally helpful. I do like the figure in it and the colorful sky. There is a good picture hiding under there.</td>', 'It looks like there is a film or something over the picture. You have no real black- I can understand that you may have been trying to perhaps get some more detail from the shadows but it makes the overall picture look washed out.  A bit of contrast is generally helpful. I do like the figure in it and the colorful sky. There is a good picture hiding under there.', '2008-12-08 01:46:52.000000', NULL, 1),
(5115883, 745439, 43088, '<td valign="top">A challenge to the voters by daring to do something different! Good for you! You will probably get killed by the voters but you get mine. 7.</td>', 'A challenge to the voters by daring to do something different! Good for you! You will probably get killed by the voters but you get mine. 7.', '2008-12-08 01:48:45.000000', NULL, 1),
(5115888, 745539, 43088, '<td valign="top">Is is because you pushed the colors too much or over-sharpened it but there are halos around the trees. Composition is very good.</td>', 'Is is because you pushed the colors too much or over-sharpened it but there are halos around the trees. Composition is very good.', '2008-12-08 01:51:04.000000', NULL, 1),
(5115890, 745038, 43088, '<td valign="top">Beautifully chilly.</td>', 'Beautifully chilly.', '2008-12-08 01:52:22.000000', NULL, 1),
(5115894, 745635, 43088, '<td valign="top">Darn, you missed the sunset. Or are too early for sunrise. Might as well go back to bed. Hehe.</td>', 'Darn, you missed the sunset. Or are too early for sunrise. Might as well go back to bed. Hehe.', '2008-12-08 01:53:13.000000', NULL, 1),
(5115895, 744618, 43088, '<td valign="top">The colors are wonderful but it is hard to tell just what you are trying to take a picture of. I think the tree is the biggest problem on this one.</td>', 'The colors are wonderful but it is hard to tell just what you are trying to take a picture of. I think the tree is the biggest problem on this one.', '2008-12-08 01:54:44.000000', NULL, 1),
(5115896, 745525, 674, '<td valign="top">Looks a little too sharp on the ripples but a nice composition.</td>', 'Looks a little too sharp on the ripples but a nice composition.', '2008-12-08 01:54:54.000000', NULL, 1),
(5115901, 745566, 674, '<td valign="top">The figure at the top gives scale to this ould have bee n nice to get the figure reflected in the water too! good colours.</td>', 'The figure at the top gives scale to this ould have bee n nice to get the figure reflected in the water too! good colours.', '2008-12-08 01:56:41.000000', NULL, 1),
(5115902, 745502, 43088, '<td valign="top">You have a very interesting sky to work with but instead most of the frame is filed with the much less interesting field of melting snow.  Could have been better. Try getting closer to the buildings or aiming higher. You probalby lose the mountains in the background if you were closer though so aim higher.</td>', 'You have a very interesting sky to work with but instead most of the frame is filed with the much less interesting field of melting snow.  Could have been better. Try getting closer to the buildings or aiming higher. You probalby lose the mountains in the background if you were closer though so aim higher.', '2008-12-08 01:57:43.000000', NULL, 1),
