(5117284, 744791, 99412, '<td valign="top">Beautiful sunrise. I wish that the crooked sign were not in the photo.You would have scored much higher but it''s still a very nice photo. I scored it according to the photo minus a little for the distraction of the sign.<br/>:)</td>', 'Beautiful sunrise. I wish that the crooked sign were not in the photo.You would have scored much higher but it''s still a very nice photo. I scored it according to the photo minus a little for the distraction of the sign.:)', '2008-12-08 13:23:05.000000', NULL, 1),
(5117289, 745634, 72068, '<td valign="top">This is great, so well balanced, the colouring is what you expect, not overly post processed. Excellent stuff!</td>', 'This is great, so well balanced, the colouring is what you expect, not overly post processed. Excellent stuff!', '2008-12-08 13:24:15.000000', NULL, 1),
