(5125100, 744618, 68947, '<td valign="top">This is so strangely interesting!  It really captures an emotion and is really quite a lovely shot and pleasing shot, even though not a technical masterpiece that is often the high score receivers in here.  I really and truly love this shot.  Captured my attention and made me come back to it for another look! :)</td>', 'This is so strangely interesting!  It really captures an emotion and is really quite a lovely shot and pleasing shot, even though not a technical masterpiece that is often the high score receivers in here.  I really and truly love this shot.  Captured my attention and made me come back to it for another look! :)', '2008-12-11 13:59:35.000000', NULL, 1),
(5125279, 745551, 56275, '<td valign="top">Would prefer the frame to be moved more towards the right.. to include the sun, and move the couple a little more off center.</td>', 'Would prefer the frame to be moved more towards the right.. to include the sun, and move the couple a little more off center.', '2008-12-11 14:55:59.000000', NULL, 1),
