(5128400, 745204, 93565, '<td valign="top">This was my favorite from the challenge. Love the blurred foam, and the rocky outcropping extening out with the lighthouse is great. The clouds really add a sense of the dramatic to this, emphasizing the magnitude of everything. A smidgeon of the sky appears blown out, but that''s nitpicking.</td>', 'This was my favorite from the challenge. Love the blurred foam, and the rocky outcropping extening out with the lighthouse is great. The clouds really add a sense of the dramatic to this, emphasizing the magnitude of everything. A smidgeon of the sky appears blown out, but that''s nitpicking.', '2008-12-13 07:59:07.000000', NULL, 1),
(5128481, 745591, 100975, '<td valign="top">I like the photo.  I think it would be better if you cut about 2 or 3 inches off of the bottom.</td>', 'I like the photo.  I think it would be better if you cut about 2 or 3 inches off of the bottom.', '2008-12-13 09:29:42.000000', NULL, 1),
(5128482, 745538, 100975, '<td valign="top">Nice composition.</td>', 'Nice composition.', '2008-12-13 09:30:11.000000', NULL, 1),
