(5129496, 745159, 62187, '<td valign="top">For me, too much extra stuff and not enough sun set/rise. Those are some awesome colors though.</td>', 'For me, too much extra stuff and not enough sun set/rise. Those are some awesome colors though.', '2008-12-13 20:28:50.000000', NULL, 1),
(5129499, 745620, 62187, '<td valign="top">Another cartoonish looking shot that is very cool but kinda overdone lately. It doesn''t look real to me and it''s more about the beach then the sunset/rise.</td>', 'Another cartoonish looking shot that is very cool but kinda overdone lately. It doesn''t look real to me and it''s more about the beach then the sunset/rise.', '2008-12-13 20:30:57.000000', NULL, 1),
(5129502, 745538, 62187, '<td valign="top">In a recent challenge, I was told the Yucca in my photo were ''unattractive''. Yeah...these look like Yucca to me but they are not unattractive: I like them.</td>', 'In a recent challenge, I was told the Yucca in my photo were ''unattractive''. Yeah...these look like Yucca to me but they are not unattractive: I like them.', '2008-12-13 20:32:20.000000', NULL, 1),
