(5129678, 744775, 62187, '<td valign="top">To me, it''s a super lovely photo with just a hint of sunrise/set.</td>', 'To me, it''s a super lovely photo with just a hint of sunrise/set.', '2008-12-13 22:38:01.000000', NULL, 1),
(5129679, 745482, 62187, '<td valign="top">It''s kinda like a ''Where''s Waldo'' huh!?!?!?!?! Not much sunset/rise going on really.</td>', 'It''s kinda like a ''Where''s Waldo'' huh!?!?!?!?! Not much sunset/rise going on really.', '2008-12-13 22:38:40.000000', NULL, 1),
